-- SCHRITT 3: Nachdem 02_family_bootstrap.sql ausgeführt wurde.
-- Erwartet GENAU eine Familie in diesem dedizierten Projekt.
-- Seed lässt vorhandene Bearbeitungen bei erneutem Ausführen unverändert.
do $$ begin
  if (select count(*) from public.families) <> 1 then
    raise exception 'Erwartet genau eine Familie. Erst Schritt 2 durchführen.';
  end if;
end $$;
insert into public.recipes(id, data, family_id)
select r.id, r.data, (select id from public.families limit 1)
from (values
  ('soba', '{"id":"soba","title":"Soba-Nudeln mit Sesam-Tofu und Edamame","category":"abend","cuisine":"Asiatisch","minutes":35,"servings":5,"servingLabel":"Personen","description":"Knuspriger Tofu, grüne Edamame und cremige Erdnuss-Ingwer-Sauce.","note":"Soba enthält häufig Weizen; Soja, Erdnüsse und Sesam sind typische Allergene.","ingredients":[{"name":"Soba-Nudeln","qty":450,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Naturtofu, fest","qty":550,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Edamame, geschält (TK)","qty":400,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Brokkoli","qty":600,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Karotten","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Rapsöl","qty":2,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Speisestärke","qty":1,"unit":"EL","group":"Gewürze & Sonstiges","optional":false},{"name":"Sesam","qty":2,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Sojasauce, natriumreduziert","qty":4,"unit":"EL","group":"Gewürze & Sonstiges","optional":false},{"name":"Erdnussmus","qty":35,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Ingwer","qty":20,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":1,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Sesamöl","qty":1,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Limette","qty":0.5,"unit":"Stk","group":"Gemüse & Obst","optional":true}],"steps":[{"title":"Tofu trocken pressen","body":"Den Tofu trocken drücken und in 2 cm große Würfel schneiden. Mit Speisestärke bestäuben.","mode":"hand"},{"title":"Tofu goldbraun braten","body":"Rapsöl in einer großen Pfanne erhitzen und den Tofu von allen Seiten kräftig knusprig braten. Danach beiseitestellen.","mode":"pfanne","minutes":10},{"title":"Gemüse und Nudeln garen","body":"Brokkoli bissfest dämpfen, Edamame nach Packungsangabe vollständig garen und Karotten fein schneiden. Soba-Nudeln separat kochen.","mode":"topf","minutes":8},{"title":"Erdnuss-Ingwer-Sauce im TM6","body":"Ingwer und Knoblauch 5 Sek. / Stufe 7 zerkleinern. Sojasauce, Erdnussmus, Sesamöl und 80–100 g warmes Wasser zugeben; 15 Sek. / Stufe 5 vermengen.","mode":"tm6"},{"title":"Alles vermengen","body":"Nudeln, Gemüse und Sauce in der Pfanne durchschwenken. Falls nötig etwas Nudelwasser ergänzen.","mode":"pfanne","minutes":2},{"title":"Anrichten","body":"Tofu erst am Schluss daraufgeben und mit trocken angeröstetem Sesam bestreuen.","mode":"hand"}],"image":"soba.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('mujadara', '{"id":"mujadara","title":"Mujadara mit Röstzwiebeln und Gurkenjoghurt","category":"abend","cuisine":"Levante","minutes":45,"servings":5,"servingLabel":"Personen","description":"Ein schlichtes levantinisches Gericht mit intensiv karamellisierten Zwiebeln.","note":"Zwiebeln in der Pfanne braten – dort entwickeln sie bessere Röstaromen als im Thermomix.","ingredients":[{"name":"Linsen, braun oder grün, trocken","qty":350,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Basmatireis","qty":300,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Zwiebeln","qty":650,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Olivenöl","qty":3,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Kreuzkümmel, gemahlen","qty":2,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Koriander, gemahlen","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Zimt","qty":0.25,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Naturjoghurt","qty":350,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Salatgurke","qty":0.5,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":1,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Minze und Petersilie","qty":1,"unit":"Bund","group":"Gemüse & Obst","optional":false}],"steps":[{"title":"Linsen kochen","body":"Linsen abspülen und in Wasser etwa 20–30 Minuten bissfest kochen, dann abgießen.","mode":"topf","minutes":25},{"title":"Reis garen","body":"Reis waschen und nach Packungsangabe garen.","mode":"topf","minutes":15},{"title":"Zwiebeln karamellisieren","body":"Zwiebeln in feine Halbringe schneiden. In Olivenöl bei mittlerer Hitze etwa 25–30 Minuten langsam dunkelgolden braten. Nicht nur glasig dünsten.","mode":"pfanne","minutes":25},{"title":"Würzen","body":"Kreuzkümmel, Koriander und Zimt mit den Zwiebeln kurz anrösten.","mode":"pfanne","minutes":1},{"title":"Gurkenjoghurt im TM6","body":"Knoblauch und Kräuter 5 Sek. / Stufe 7 zerkleinern; Naturjoghurt und Salz 10 Sek. / Stufe 3 verrühren. Fein gewürfelte Gurke von Hand unterheben.","mode":"tm6"},{"title":"Servieren","body":"Reis, Linsen und zwei Drittel der Zwiebeln mischen. Die übrigen Zwiebeln darüber verteilen und Gurkenjoghurt dazugeben.","mode":"hand"}],"image":"mujadara.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('kokos', '{"id":"kokos","title":"Ingwer-Kokos-Hähnchen mit Edamame","category":"abend","cuisine":"Asiatisch","minutes":35,"servings":5,"servingLabel":"Personen","description":"Mild, aromatisch und cremig mit Kokos, Ingwer und Sojabohnen.","note":"Edamame müssen vollständig gegart werden.","ingredients":[{"name":"Hähnchenbrust","qty":750,"unit":"g","group":"Fisch & Fleisch","optional":false},{"name":"Jasminreis","qty":350,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Edamame, geschält (TK)","qty":350,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Zucchini","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Paprika","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Babyspinat","qty":200,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Kokosmilch","qty":400,"unit":"ml","group":"Gewürze & Sonstiges","optional":false},{"name":"Gemüsebrühe","qty":250,"unit":"ml","group":"Gewürze & Sonstiges","optional":false},{"name":"Ingwer","qty":25,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":2,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Zitronengras","qty":1,"unit":"Stange","group":"Gemüse & Obst","optional":false},{"name":"Rapsöl","qty":2,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Sojasauce, natriumreduziert","qty":2,"unit":"EL","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Reis kochen","body":"Jasminreis nach Packungsangabe in einem separaten Topf garen.","mode":"topf","minutes":15},{"title":"Hähnchen kräftig anbraten","body":"Hähnchen in Streifen schneiden und portionsweise in heißem Rapsöl bräunen, herausnehmen.","mode":"pfanne","minutes":6},{"title":"Gemüse anrösten","body":"Zucchini und Paprika würfeln und in derselben Pfanne kräftig anbraten.","mode":"pfanne","minutes":5},{"title":"Saucenbasis im TM6","body":"Ingwer und Knoblauch 5 Sek. / Stufe 7 zerkleinern. 1 TL Öl ergänzen und 3 Min. / 120 °C / Stufe 1 dünsten. Kokosmilch, Brühe und Sojasauce zugeben; 5 Min. / 100 °C / Stufe 1 erhitzen.","mode":"tm6","minutes":5},{"title":"Fertig garen","body":"Sauce zum Gemüse geben, angedrücktes Zitronengras, Hähnchen und Edamame hinzufügen. 7–10 Minuten sanft köcheln, bis Fleisch und Sojabohnen vollständig gar sind.","mode":"pfanne","minutes":10},{"title":"Spinat ergänzen und servieren","body":"Zitronengras entfernen, Spinat kurz zusammenfallen lassen und mit Reis anrichten.","mode":"hand"}],"image":"kokos.webp","tags":["geflügel","thermomix"]}'::jsonb),
  ('blumenkohl', '{"id":"blumenkohl","title":"Gerösteter Blumenkohl, Kichererbsen und Tahini","category":"abend","cuisine":"Levante","minutes":40,"servings":5,"servingLabel":"Personen","description":"Knusprige Kichererbsen und Blumenkohl mit cremiger Sesamsauce.","note":"Die Kichererbsen vor dem Rösten gut trocknen.","ingredients":[{"name":"Blumenkohl","qty":1300,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Kichererbsen, abgetropft","qty":720,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Bulgur","qty":300,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Olivenöl","qty":3,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Za''atar","qty":2,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Kreuzkümmel, gemahlen","qty":1,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Tahini","qty":80,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Griechischer Joghurt","qty":250,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Knoblauch","qty":1,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Petersilie","qty":1,"unit":"Bund","group":"Gemüse & Obst","optional":false},{"name":"Zitrone","qty":1,"unit":"Stk","group":"Gemüse & Obst","optional":true}],"steps":[{"title":"Backofen vorheizen","body":"Auf 220 °C Umluft vorheizen. Blumenkohl in Röschen schneiden, Kichererbsen abspülen und gründlich trocknen.","mode":"ofen"},{"title":"Würzen","body":"Blumenkohl und Kichererbsen mit Olivenöl, Za’atar, Kreuzkümmel und etwas Salz vermengen.","mode":"hand"},{"title":"Auf zwei Blechen rösten","body":"Locker verteilen, 25–30 Minuten kräftig rösten und zwischendurch wenden.","mode":"ofen","minutes":30},{"title":"Bulgur garen","body":"Bulgur nach Packungsanweisung mit heißem Wasser quellen lassen.","mode":"topf","minutes":15},{"title":"Tahinisauce im TM6","body":"Knoblauch 5 Sek. / Stufe 7 zerkleinern. Tahini, Joghurt und 60–100 g Wasser hinzugeben; 20 Sek. / Stufe 4 verrühren.","mode":"tm6"},{"title":"Anrichten","body":"Bulgur auf Teller verteilen, Röstgemüse darübergeben. Mit Tahinisauce und Petersilie servieren.","mode":"hand"}],"image":"blumenkohl.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('lachs', '{"id":"lachs","title":"Miso-Lachs mit Süßkartoffeln und Brokkoli","category":"abend","cuisine":"Asiatisch","minutes":45,"servings":5,"servingLabel":"Personen","description":"Herzhafte Misoglasur trifft auf süß geröstete Kartoffeln und Brokkoli.","note":"Ofenbleche nicht überfüllen; sonst dämpft das Gemüse.","ingredients":[{"name":"Lachsfilet","qty":900,"unit":"g","group":"Fisch & Fleisch","optional":false},{"name":"Süßkartoffeln","qty":1200,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Brokkoli","qty":800,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Olivenöl","qty":3,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Sesam","qty":2,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Helle Misopaste","qty":35,"unit":"g","group":"Gewürze & Sonstiges","optional":false},{"name":"Sojasauce, natriumreduziert","qty":1,"unit":"EL","group":"Gewürze & Sonstiges","optional":false},{"name":"Honig","qty":1,"unit":"EL","group":"Gewürze & Sonstiges","optional":false},{"name":"Ingwer","qty":15,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":1,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Griechischer Joghurt","qty":250,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Tahini","qty":25,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Sesamöl","qty":1,"unit":"TL","group":"Nüsse, Samen & Fette","optional":false}],"steps":[{"title":"Süßkartoffeln rösten","body":"Backofen auf 210 °C Ober-/Unterhitze vorheizen. Süßkartoffeln in 2 cm große Würfel schneiden, mit 2 EL Öl vermengen, auf einem Blech 20 Minuten vorbacken.","mode":"ofen","minutes":20},{"title":"Brokkoli vorbereiten","body":"Brokkoli in Röschen teilen, gut trocknen und mit 1 EL Öl mischen. Nach 20 Minuten auf einem zweiten Blech in den Ofen geben.","mode":"ofen"},{"title":"Misoglasur im TM6","body":"Ingwer und Knoblauch 5 Sek. / Stufe 7 zerkleinern. Misopaste, Sojasauce, Honig und 30 g Wasser zugeben; 15 Sek. / Stufe 4 verrühren.","mode":"tm6"},{"title":"Lachs garen","body":"Temperatur auf 190 °C senken. Lachs in fünf Portionen teilen, mit Glasur bestreichen. Auf separatem Blech 12–16 Minuten garen (Dicke beachten), bis vollständig durchgegart.","mode":"ofen","minutes":14},{"title":"Sesam-Joghurt im TM6","body":"Griechischen Joghurt, Tahini, Sesamöl, etwas Ingwer und Wasser 15 Sek. / Stufe 3 verrühren.","mode":"tm6"},{"title":"Anrichten","body":"Sesam trocken rösten und über Lachs, Süßkartoffeln und Brokkoli streuen. Dip dazu reichen.","mode":"hand"}],"image":"lachs.webp","tags":["fisch","thermomix"]}'::jsonb),
  ('shawarma', '{"id":"shawarma","title":"Hähnchen-Shawarma mit Hummus und Fladenbrot","category":"abend","cuisine":"Levante","minutes":45,"servings":5,"servingLabel":"Personen","description":"Würziges Hähnchen, Hummus und frischer Gurkensalat zum Selbstfüllen.","note":"Marinierzeit ist zusätzlich zur aktiven Kochzeit; Zutaten und Zeitangaben sind Richtwerte.","ingredients":[{"name":"Hähnchenoberkeulen, ausgelöst","qty":850,"unit":"g","group":"Fisch & Fleisch","optional":false},{"name":"Naturjoghurt","qty":350,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Olivenöl","qty":40,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Knoblauch","qty":3,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Kreuzkümmel, gemahlen","qty":2,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Koriander, gemahlen","qty":1,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Paprikapulver, edelsüß","qty":1,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Kurkuma","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Zimt","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Piment","qty":0.25,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Kichererbsen, abgetropft","qty":480,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Tahini","qty":70,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Fladenbrot, groß","qty":5,"unit":"Stk","group":"Getreide & Kartoffeln","optional":false},{"name":"Salatgurke","qty":1,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Rote Zwiebeln","qty":1,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Petersilie und Minze","qty":1,"unit":"Bund","group":"Gemüse & Obst","optional":false},{"name":"Zitrone","qty":1,"unit":"Stk","group":"Gemüse & Obst","optional":true}],"steps":[{"title":"Marinade im TM6","body":"2 Knoblauchzehen 5 Sek. / Stufe 7 zerkleinern. 100 g Joghurt, Öl und Gewürze zugeben, 10 Sek. / Stufe 3 mischen.","mode":"tm6"},{"title":"Hähnchen marinieren","body":"Hähnchen in Streifen schneiden, mit Marinade vermengen und idealerweise 1–3 Stunden gekühlt ziehen lassen.","mode":"hand","minutes":60},{"title":"Hummus im TM6","body":"Kichererbsen, 70 g Tahini, 1 Knoblauchzehe, Olivenöl, Kreuzkümmel, Salz und 100 g kaltes Wasser 30 Sek. / Stufe 6, dann 30 Sek. / Stufe 8 pürieren. Wasser ergänzen, bis cremig.","mode":"tm6"},{"title":"Salat vorbereiten","body":"Gurke und rote Zwiebel klein schneiden; mit Petersilie und Minze vermengen. Übrigen Naturjoghurt als Sauce abschmecken.","mode":"hand"},{"title":"Hähnchen braten","body":"Streifen portionsweise kräftig anbraten und vollständig durchgaren.","mode":"pfanne","minutes":12},{"title":"Fladenbrot erwärmen und servieren","body":"Mit Hummus, Hähnchen, Gurkensalat und Joghurtsauce füllen.","mode":"hand"}],"image":"shawarma.webp","tags":["geflügel","thermomix"]}'::jsonb),
  ('rigatoni', '{"id":"rigatoni","title":"Rigatoni mit Hokkaido, Linsen und Salbei","category":"abend","cuisine":"Italienisch","minutes":45,"servings":5,"servingLabel":"Personen","description":"Intensive Kürbissauce durch Rösten, mit Linsen und knusprigem Salbei.","note":"Mit Nudelwasser die Sauce seidig binden.","ingredients":[{"name":"Rigatoni","qty":550,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Hokkaido","qty":800,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Rote Linsen, trocken","qty":160,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Zwiebeln","qty":1,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":2,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Gemüsebrühe","qty":400,"unit":"ml","group":"Gewürze & Sonstiges","optional":false},{"name":"Parmesan","qty":60,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Olivenöl","qty":3,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Salbeiblätter","qty":12,"unit":"Stk","group":"Gemüse & Obst","optional":false}],"steps":[{"title":"Kürbis rösten","body":"Hokkaido in Würfel schneiden und mit 2 EL Olivenöl bei 220 °C Ober-/Unterhitze 25–30 Minuten kräftig rösten.","mode":"ofen","minutes":28},{"title":"Aromabasis im TM6","body":"Zwiebel und Knoblauch 5 Sek. / Stufe 5 zerkleinern. 1 EL Olivenöl zugeben; 3 Min. / 120 °C / Stufe 1 dünsten.","mode":"tm6","minutes":3},{"title":"Linsen garen","body":"Abgespülte rote Linsen und Gemüsebrühe zugeben; 16 Min. / 100 °C / Linkslauf / Stufe 1. Bei Bedarf verlängern.","mode":"tm6","minutes":16},{"title":"Kürbiscreme pürieren","body":"Etwa zwei Drittel des gerösteten Hokkaidos zur Linsenbasis geben und 20–30 Sek. / Stufe 6 pürieren.","mode":"tm6"},{"title":"Pasta & Salbei vorbereiten","body":"Rigatoni knapp al dente kochen und Nudelwasser aufheben. Salbeiblätter in wenig Öl knusprig braten.","mode":"topf","minutes":12},{"title":"Cremig vollenden","body":"Pasta mit Kürbis-Linsen-Creme, restlichem Kürbis, Parmesan und etwas Nudelwasser vermengen. Mit Salbei und Pfeffer servieren.","mode":"hand"}],"image":"rigatoni.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('paccheri', '{"id":"paccheri","title":"Paccheri mit Zucchini-Parmesan-Creme","category":"abend","cuisine":"Italienisch","minutes":30,"servings":5,"servingLabel":"Personen","description":"Cremige Zucchinipasta mit Röstaromen und knusprigen Pinienkernen.","note":"Die Kinder mögen keine Champignons: bewusst ganz ohne Pilze.","ingredients":[{"name":"Paccheri","qty":550,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Zucchini","qty":900,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Schalotten","qty":1,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":2,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Parmesan","qty":70,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Pinienkerne","qty":50,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Olivenöl","qty":3,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Basilikum","qty":1,"unit":"Bund","group":"Gemüse & Obst","optional":false},{"name":"Erbsen (TK)","qty":250,"unit":"g","group":"Gemüse & Obst","optional":true}],"steps":[{"title":"Zucchini schneiden","body":"Zucchini in grobe Würfel oder Halbmonde schneiden.","mode":"hand"},{"title":"Pinienkerne rösten","body":"Pinienkerne ohne Öl in einer Pfanne goldbraun rösten und herausnehmen.","mode":"pfanne","minutes":3},{"title":"Zucchini kräftig anbraten","body":"Zucchini portionsweise kräftig braten. Ein Drittel der gebräunten Stücke beiseitestellen.","mode":"pfanne","minutes":10},{"title":"Pasta kochen","body":"Paccheri knapp al dente garen, etwa 250 ml Kochwasser aufheben.","mode":"topf","minutes":12},{"title":"Zucchinicreme im TM6","body":"Parmesan 10 Sek. / Stufe 10 zerkleinern und umfüllen. Schalotte und Knoblauch 5 Sek. / Stufe 5 zerkleinern, mit wenig Öl 3 Min. / 120 °C / Stufe 1 dünsten. Gebratene Zucchini, 120 ml Nudelwasser, Parmesan und Basilikum 25 Sek. / Stufe 6–8 pürieren.","mode":"tm6"},{"title":"Finalisieren","body":"Paccheri mit Creme und übrigen Zucchini mischen. Bei Bedarf Wasser ergänzen und mit Pinienkernen und Basilikum servieren.","mode":"hand"}],"image":"paccheri.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('koefte', '{"id":"koefte","title":"Smashed Potatoes mit Köfte und Tahini-Joghurt","category":"abend","cuisine":"Levante","minutes":55,"servings":5,"servingLabel":"Personen","description":"Kartoffelcrunch mit herzhaften Köfte und frischem Tahini-Joghurt.","note":"Die Köfte können getrennt serviert werden, wenn Kinder einzelne Komponenten nicht mögen.","ingredients":[{"name":"Kartoffeln, festkochend","qty":1300,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Rinderhackfleisch, mager","qty":500,"unit":"g","group":"Fisch & Fleisch","optional":false},{"name":"Paprika","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Zucchini","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Rote Zwiebeln","qty":1,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":3,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Olivenöl","qty":3,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Kreuzkümmel, gemahlen","qty":2,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Koriander, gemahlen","qty":1,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Paprikapulver, edelsüß","qty":1,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Zimt","qty":0.25,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Petersilie","qty":0.5,"unit":"Bund","group":"Gemüse & Obst","optional":false},{"name":"Naturjoghurt","qty":350,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Tahini","qty":40,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Minze","qty":0.5,"unit":"Bund","group":"Gemüse & Obst","optional":false}],"steps":[{"title":"Kartoffeln vorkochen","body":"Kleine Kartoffeln mit Schale 15–20 Minuten knapp weich kochen. Abgießen und etwas ausdampfen lassen.","mode":"topf","minutes":18},{"title":"Kartoffeln zerdrücken und rösten","body":"Auf ein Blech legen, mit einem Glas leicht flach drücken, mit Öl und Salz würzen. Bei 220 °C Umluft 25–30 Minuten knusprig rösten.","mode":"ofen","minutes":28},{"title":"Gemüse mitrösten","body":"Paprika und Zucchini würfeln, mit 1 EL Öl mischen und auf einem zweiten Blech 20–25 Minuten mitrösten.","mode":"ofen","minutes":22},{"title":"Köfte-Masse vorbereiten","body":"Zwiebel, 2 Knoblauchzehen und Petersilie 5 Sek. / Stufe 5 im TM6 zerkleinern. Mit Hack, Kreuzkümmel, Koriander, Paprika, Zimt, Salz und Pfeffer mischen. 15 kleine Köfte formen.","mode":"tm6"},{"title":"Köfte braten","body":"In einer großen Pfanne rundherum kräftig anbraten und vollständig durchgaren.","mode":"pfanne","minutes":12},{"title":"Tahini-Joghurt im TM6","body":"Restlichen Knoblauch und Minze 5 Sek. / Stufe 7 zerkleinern. Naturjoghurt, Tahini und 30–50 g Wasser zugeben; 15 Sek. / Stufe 4 verrühren.","mode":"tm6"},{"title":"Alles anrichten","body":"Smashed Potatoes, Köfte und Gemüse mit der Tahinisauce servieren.","mode":"hand"}],"image":"koefte.webp","tags":["rind","thermomix"]}'::jsonb),
  ('roesti', '{"id":"roesti","title":"Kartoffelrösti mit Spitzkohl, Apfel und Kräuterquark","category":"abend","cuisine":"Deutsch","minutes":55,"servings":5,"servingLabel":"Personen","description":"Klassisch deutsche Küche mit modernem Gemüse-Twist und knusprigen Rösti.","note":"Die Kinder können alternativ etwas Möhren-Lauch-Gemüse statt Spitzkohl bekommen.","ingredients":[{"name":"Kartoffeln, vorwiegend festkochend","qty":1400,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Spitzkohl","qty":800,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Äpfel","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Zwiebeln","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Eier","qty":2,"unit":"Stk","group":"Milchprodukte & Eier","optional":false},{"name":"Speisestärke","qty":40,"unit":"g","group":"Gewürze & Sonstiges","optional":false},{"name":"Rapsöl","qty":4,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Magerquark","qty":400,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Naturjoghurt","qty":200,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Mittelscharfer Senf","qty":2,"unit":"EL","group":"Gewürze & Sonstiges","optional":false},{"name":"Schnittlauch und Petersilie","qty":1,"unit":"Bund","group":"Gemüse & Obst","optional":false},{"name":"Gemüsebrühe","qty":100,"unit":"ml","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Kartoffeln grob zerkleinern","body":"Kartoffeln schälen und im Thermomix portionsweise jeweils 3–4 Sek. / Stufe 4 grob zerkleinern, nicht pürieren. In einem Küchentuch gründlich ausdrücken.","mode":"tm6"},{"title":"Röstimasse herstellen","body":"Eine fein gehackte Zwiebel mit Kartoffeln, Eiern, Stärke, Salz und Muskat vermengen.","mode":"hand"},{"title":"Rösti braten","body":"In zwei Pfannen portionsweise insgesamt etwa 15 kleine Rösti in Rapsöl knusprig braten. Bei 100 °C im Ofen warm halten.","mode":"pfanne","minutes":20},{"title":"Spitzkohl anbraten","body":"Spitzkohl in Streifen schneiden. Zweite Zwiebel anbraten, Kohl ergänzen und zunächst kräftig bräunen.","mode":"pfanne","minutes":8},{"title":"Mit Apfel schmoren","body":"Apfelspalten kurz mitbraten, Gemüsebrühe zugeben und 5 Minuten sanft schmoren. Mit Kümmel, Pfeffer und Salz würzen.","mode":"pfanne","minutes":5},{"title":"Kräuterquark im TM6","body":"Kräuter 5 Sek. / Stufe 6 hacken. Quark, Joghurt und Senf hinzugeben, 15 Sek. / Stufe 3 verrühren.","mode":"tm6"},{"title":"Servieren","body":"Kartoffelrösti mit reichlich Spitzkohl-Apfel-Gemüse und Senf-Kräuterquark anrichten.","mode":"hand"}],"image":"roesti.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('airfryer', '{"id":"airfryer","title":"Crispy Potato Bowl mit Spinat, Feta und Kräuterquark","category":"abend","cuisine":"Mediterran","minutes":50,"servings":5,"servingLabel":"Personen","description":"Knusprige Kartoffelspalten mit grünen Gemüsekomponenten und cremigem Dip.","note":"Viele kleine Airfryer benötigen mehrere Chargen.","ingredients":[{"name":"Kartoffeln, vorwiegend festkochend","qty":1500,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Babyspinat","qty":400,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Erbsen (TK)","qty":350,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Feta","qty":200,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Magerquark","qty":350,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Naturjoghurt","qty":200,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Rote Zwiebeln","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Knoblauch","qty":2,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Olivenöl","qty":3,"unit":"EL","group":"Nüsse, Samen & Fette","optional":false},{"name":"Paprikapulver, geräuchert","qty":1,"unit":"TL","group":"Gewürze & Sonstiges","optional":false},{"name":"Schnittlauch und Petersilie","qty":1,"unit":"Bund","group":"Gemüse & Obst","optional":false},{"name":"Mandeln, gehackt","qty":40,"unit":"g","group":"Nüsse, Samen & Fette","optional":true}],"steps":[{"title":"Kartoffeln vorgaren","body":"Kartoffeln waschen, in Spalten schneiden und in leicht gesalzenem Wasser 8–10 Minuten vorgaren. Abgießen und ausdampfen lassen.","mode":"topf","minutes":10},{"title":"Würzen","body":"Mit 2 EL Olivenöl, geräuchertem Paprikapulver und Pfeffer vermischen.","mode":"hand"},{"title":"Im Airfryer knusprig rösten","body":"Bei 200 °C etwa 18–25 Minuten backen, zwischendurch wenden. Für 1,5 kg je nach Gerät 2–3 Chargen einplanen.","mode":"airfryer","minutes":22},{"title":"Spinat und Erbsen","body":"Rote Zwiebeln anbraten, Knoblauch dazugeben, Erbsen mit etwas Wasser 5 Minuten garen. Spinat zugeben und zusammenfallen lassen. Mit Muskat abschmecken.","mode":"pfanne","minutes":8},{"title":"Kräuterquark im TM6","body":"Kräuter 5 Sek. / Stufe 6 zerkleinern. Quark, Naturjoghurt und Pfeffer zugeben; 15 Sek. / Stufe 3 verrühren.","mode":"tm6"},{"title":"Feta und Topping","body":"Feta über das Gemüse bröseln. Optional kurz in einer kleinen hitzebeständigen Form im Airfryer anwärmen; Mandeln trocken rösten.","mode":"airfryer","minutes":4},{"title":"Bowl anrichten","body":"Kartoffeln mit Spinat-Erbsen-Gemüse und Feta anrichten; Kräuterquark darüber oder daneben servieren.","mode":"hand"}],"image":"airfryer.webp","tags":["vegetarisch","airfryer","thermomix"]}'::jsonb),
  ('brot', '{"id":"brot","title":"Vollkornbrot mit Übernachtgare","category":"brot","cuisine":"Backen","minutes":80,"servings":1,"servingLabel":"Brot","description":"90 % Weizenvollkorn, ohne Sonnenblumenkerne, auf den Ofenmeister abgestimmt.","note":"Backmalz nur verwenden, wenn es sicher enzym-inaktiv ist. 80 Minuten meint reine Backzeit; Übernachtgare kommt hinzu. Temperaturfreigabe des Ofenmeister-Modells beachten.","ingredients":[{"name":"Weizenvollkornmehl","qty":675,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Roggenmehl Type 1150","qty":75,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Wasser","qty":600,"unit":"g","group":"Gewürze & Sonstiges","optional":false},{"name":"Trockenhefe","qty":2,"unit":"g","group":"Gewürze & Sonstiges","optional":false},{"name":"Salz","qty":16,"unit":"g","group":"Gewürze & Sonstiges","optional":false},{"name":"Backmalz, enzym-inaktiv","qty":9,"unit":"g","group":"Gewürze & Sonstiges","optional":true}],"steps":[{"title":"21:00 – Teig in zwei Portionen kneten","body":"Je Portion etwa 337–338 g Weizenvollkornmehl, 37–38 g Roggenmehl, 300 g Wasser, 1 g Trockenhefe und 8 g Salz. Je 4 Min. / Teigstufe kneten. Teigportionen zusammenführen.","mode":"tm6","minutes":4},{"title":"21:30 – Erstes Falten","body":"Den Teig abgedeckt bei Raumtemperatur stehen lassen. Mit nassen Händen von vier Seiten zur Mitte falten.","mode":"hand"},{"title":"22:00 – Zweites Falten und formen","body":"Noch einmal falten und zu einem länglichen Laib formen. Mit Schluss nach oben in ein bemehltes Gärkörbchen legen.","mode":"hand"},{"title":"22:15 – Kaltgare","body":"Gut abgedeckt bei etwa 4–5 °C in den Kühlschrank stellen. Nicht im Ofenmeister kalt lagern.","mode":"kuehlschrank"},{"title":"07:30 – Backbereit machen","body":"Gare prüfen: Der Teig sollte deutlich aufgegangen sein. Auf leichten Druck sollte er langsam zurückfedern. Bei Untergare 30–60 Minuten weiter ruhen lassen.","mode":"hand"},{"title":"Im Ofenmeister backen","body":"Teig in den zimmerwarmen Ofenmeister stürzen, einschneiden, Deckel auflegen. In den kalten Ofen stellen und 230 °C Ober-/Unterhitze wählen; etwa 65–75 Minuten backen. Gegen Ende ggf. den Deckel zum Bräunen abnehmen.","mode":"ofen","minutes":70},{"title":"Brot abkühlen","body":"Kerntemperatur idealerweise 96–98 °C. Auf Gitter mindestens zwei Stunden auskühlen lassen.","mode":"hand","minutes":120}],"image":"brot.webp","tags":["thermomix","übernacht"]}'::jsonb),
  ('hummus', '{"id":"hummus","title":"Cremiger Hummus","category":"aufstrich","cuisine":"Levante","minutes":10,"servings":1,"servingLabel":"Ansatz","description":"Cremiger Aufstrich für euer Vollkornbrot.","note":"Etwa 350 g Aufstrich; innerhalb von 2–3 Tagen gekühlt verbrauchen.","ingredients":[{"name":"Kichererbsen, abgetropft","qty":240,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Tahini","qty":30,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Olivenöl","qty":15,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Wasser","qty":60,"unit":"g","group":"Gewürze & Sonstiges","optional":false},{"name":"Knoblauch","qty":0.5,"unit":"Zehe","group":"Gemüse & Obst","optional":false},{"name":"Kreuzkümmel, gemahlen","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Zutaten vorbereiten","body":"Kichererbsen abspülen, Knoblauch schälen.","mode":"hand"},{"title":"Im TM6 pürieren","body":"Alle Zutaten in den Mixtopf geben; 30 Sek. / Stufe 7, herunterschieben und weitere 20 Sek. / Stufe 7 pürieren.","mode":"tm6"},{"title":"Abschmecken","body":"Mit etwas Wasser bis zur gewünschten Streichfähigkeit verdünnen und salzen. Gekühlt aufbewahren.","mode":"hand"}],"image":"hummus.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('edamame-creme', '{"id":"edamame-creme","title":"Edamame-Tahini-Creme","category":"aufstrich","cuisine":"Asiatisch","minutes":15,"servings":1,"servingLabel":"Ansatz","description":"Frischgrüner, eiweißreicher Brotaufstrich mit Sesam.","note":"Etwa 400 g; 2–3 Tage gekühlt aufbewahren.","ingredients":[{"name":"Edamame, geschält (TK)","qty":300,"unit":"g","group":"Hülsenfrüchte & Tofu","optional":false},{"name":"Naturjoghurt","qty":70,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Tahini","qty":20,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Olivenöl","qty":10,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Petersilie","qty":0.5,"unit":"Bund","group":"Gemüse & Obst","optional":false}],"steps":[{"title":"Edamame vollständig garen","body":"Edamame nach Packungsanweisung garen und abkühlen lassen.","mode":"topf","minutes":6},{"title":"Im TM6 pürieren","body":"Gegarte Edamame, Joghurt, Tahini, Olivenöl und Petersilie 25 Sek. / Stufe 7 pürieren.","mode":"tm6"},{"title":"Abschmecken","body":"Mit etwas Wasser und Salz die gewünschte Konsistenz einstellen. Gekühlt aufbewahren.","mode":"hand"}],"image":"edamame-creme.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('paprika-creme', '{"id":"paprika-creme","title":"Paprika-Walnuss-Aufstrich","category":"aufstrich","cuisine":"Levante","minutes":35,"servings":1,"servingLabel":"Ansatz","description":"Tomatenfreie, intensiv geröstete Paprikacreme mit Walnüssen.","note":"Etwa 300 g, gekühlt 2–3 Tage verbrauchen.","ingredients":[{"name":"Paprika, rot","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Walnüsse","qty":60,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Olivenöl","qty":20,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Kreuzkümmel, gemahlen","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Paprika rösten","body":"Paprika halbieren und bei 220 °C Ober-/Unterhitze etwa 20–25 Minuten rösten. Abkühlen lassen, bei Bedarf häuten.","mode":"ofen","minutes":25},{"title":"Im TM6 mixen","body":"Paprika mit Walnüssen, Olivenöl, Kreuzkümmel und etwas Salz 15 Sek. / Stufe 5 mixen.","mode":"tm6"},{"title":"Aufstreichen","body":"Für mehr Biss nicht zu fein pürieren. Im Kühlschrank aufbewahren.","mode":"hand"}],"image":"paprika-creme.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('hafer-beere', '{"id":"hafer-beere","title":"Beeren-Walnuss-Porridge","category":"hafer","cuisine":"Müsli & Porridge","minutes":15,"servings":5,"servingLabel":"Personen","description":"Warm, cremig und reich an Ballaststoffen.","note":"Für fünf Personen kann die Mischung im TM6 je nach Füllstand zu voll sein: bei Bedarf in zwei Chargen kochen.","ingredients":[{"name":"Haferflocken","qty":350,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Milch oder Sojadrink","qty":900,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Wasser","qty":250,"unit":"ml","group":"Gewürze & Sonstiges","optional":false},{"name":"Skyr","qty":500,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Beeren","qty":450,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Walnüsse","qty":80,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Zimt","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Warme Haferbasis","body":"Haferflocken, Milch, Wasser und Zimt im TM6 10 Min. / 90 °C / Linkslauf / Stufe 2 garen. Bei Bedarf 1–2 Minuten verlängern.","mode":"tm6","minutes":10},{"title":"Toppings vorbereiten","body":"Beeren waschen und Walnüsse grob hacken. Tiefgekühlte Beeren vorab vollständig erhitzen und abkühlen lassen.","mode":"hand"},{"title":"Servieren","body":"Porridge auf fünf Schüsseln verteilen, jeweils Skyr, Beeren und Walnüsse daraufgeben.","mode":"hand"}],"image":"hafer-beere.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('hafer-overnight', '{"id":"hafer-overnight","title":"Beeren-Overnight-Oats","category":"hafer","cuisine":"Müsli & Porridge","minutes":10,"servings":5,"servingLabel":"Personen","description":"Kalte Hafermahlzeit, ideal am Vorabend vorbereitet.","note":"Zubereitungszeit ohne Kühlzeit.","ingredients":[{"name":"Haferflocken","qty":350,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Skyr","qty":600,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Milch oder Sojadrink","qty":550,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Beeren","qty":500,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Leinsamen, geschrotet","qty":50,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Walnüsse","qty":70,"unit":"g","group":"Nüsse, Samen & Fette","optional":false}],"steps":[{"title":"Hafermasse verrühren","body":"Haferflocken, Skyr, Milch und Leinsamen in einer großen Schüssel verrühren.","mode":"hand"},{"title":"Quellen lassen","body":"Abgedeckt mindestens 4 Stunden, besser über Nacht, im Kühlschrank quellen lassen.","mode":"kuehlschrank","minutes":240},{"title":"Frisch toppen","body":"Bei Bedarf mit etwas Milch lockern. Frische Beeren und Walnüsse vor dem Servieren zugeben.","mode":"hand"}],"image":"hafer-overnight.webp","tags":["vegetarisch","mealprep"]}'::jsonb),
  ('hafer-birne', '{"id":"hafer-birne","title":"Birnen-Mandel-Müsli","category":"hafer","cuisine":"Müsli & Porridge","minutes":10,"servings":5,"servingLabel":"Personen","description":"Knusprig und frisch mit Birne und Mandeln.","note":"Für weichere Flocken 20 Minuten ziehen lassen.","ingredients":[{"name":"Haferflocken","qty":350,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Naturjoghurt","qty":900,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Milch oder Sojadrink","qty":200,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Birnen","qty":4,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Mandeln","qty":90,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Kürbiskerne","qty":50,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Zimt","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Mandeln und Kürbiskerne rösten","body":"Trocken rösten, bis sie duften. Optional Mandeln im TM6 3 Sek. / Stufe 5 hacken.","mode":"pfanne","minutes":3},{"title":"Frucht und Joghurt vorbereiten","body":"Birnen klein schneiden, Joghurt mit Milch cremig rühren.","mode":"hand"},{"title":"Schichten","body":"Haferflocken, Birnen und Joghurt in Schüsseln verteilen. Mandeln und Kerne erst kurz vor dem Essen darüberstreuen.","mode":"hand"}],"image":"hafer-birne.webp","tags":["vegetarisch"]}'::jsonb),
  ('hafer-mango', '{"id":"hafer-mango","title":"Mango-Nuss-Skyr-Bowl","category":"hafer","cuisine":"Müsli & Porridge","minutes":10,"servings":5,"servingLabel":"Personen","description":"Mild-fruchtig, eiweißreich und ohne zugesetzten Zucker.","note":"Bei großem Hunger Haferportion erhöhen.","ingredients":[{"name":"Haferflocken","qty":300,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Skyr","qty":900,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Milch oder Sojadrink","qty":250,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Mango","qty":2,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Cashewkerne","qty":80,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Kokosraspel, ungesüßt","qty":40,"unit":"g","group":"Nüsse, Samen & Fette","optional":false}],"steps":[{"title":"Skyrcreme zubereiten","body":"Skyr und Milch zu einer cremigen Konsistenz verrühren; optional TM6 15 Sek. / Stufe 3.","mode":"tm6"},{"title":"Toppings vorbereiten","body":"Mango schälen und würfeln. Cashews grob hacken. Kokosraspel nach Wunsch trocken rösten.","mode":"hand"},{"title":"Schichten","body":"Haferflocken und Skyrcreme in fünf Schüsseln schichten, mit Mango, Cashews und Kokos bestreuen.","mode":"hand"}],"image":"hafer-mango.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('hafer-apfel', '{"id":"hafer-apfel","title":"Apfel-Zimt-Porridge","category":"hafer","cuisine":"Müsli & Porridge","minutes":15,"servings":5,"servingLabel":"Personen","description":"Wärmender Klassiker mit Apfel und Zimt.","note":"Große Mengen im TM6 aufteilen, falls die maximale Füllhöhe erreicht wird.","ingredients":[{"name":"Haferflocken","qty":350,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Milch oder Sojadrink","qty":900,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Wasser","qty":200,"unit":"ml","group":"Gewürze & Sonstiges","optional":false},{"name":"Äpfel","qty":3,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Skyr","qty":500,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Walnüsse","qty":75,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Zimt","qty":1,"unit":"TL","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Porridge kochen","body":"Haferflocken, Milch, Wasser und Zimt im TM6 10 Min. / 90 °C / Linkslauf / Stufe 2 garen.","mode":"tm6","minutes":10},{"title":"Äpfel vorbereiten","body":"Äpfel würfeln, auf Wunsch ohne Zucker kurz in der Pfanne erwärmen. Walnüsse hacken.","mode":"pfanne","minutes":3},{"title":"Anrichten","body":"Mit Skyr, Äpfeln und Walnüssen servieren.","mode":"hand"}],"image":"hafer-apfel.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('hafer-chia', '{"id":"hafer-chia","title":"Beeren-Chia-Quark-Bowl","category":"hafer","cuisine":"Müsli & Porridge","minutes":40,"servings":5,"servingLabel":"Personen","description":"Kalt, cremig und besonders eiweißreich.","note":"Bei großem Hunger mehr Haferflocken ergänzen.","ingredients":[{"name":"Haferflocken","qty":180,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Chiasamen","qty":75,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Magerquark","qty":850,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Naturjoghurt","qty":500,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Milch oder Sojadrink","qty":350,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Beeren","qty":500,"unit":"g","group":"Gemüse & Obst","optional":false}],"steps":[{"title":"Chia quellen lassen","body":"Chiasamen in Milch einrühren, nach fünf Minuten noch einmal umrühren und insgesamt 30 Minuten quellen lassen.","mode":"hand","minutes":30},{"title":"Cremige Basis","body":"Quark und Joghurt verrühren und mit Haferflocken und Chiamischung vermengen.","mode":"hand"},{"title":"Servieren","body":"Auf fünf Schüsseln verteilen und mit Beeren ergänzen.","mode":"hand"}],"image":"hafer-chia.webp","tags":["vegetarisch"]}'::jsonb),
  ('hafer-schoko', '{"id":"hafer-schoko","title":"Schoko-Bananen-Porridge","category":"hafer","cuisine":"Müsli & Porridge","minutes":15,"servings":5,"servingLabel":"Personen","description":"Schokoladig durch Backkakao, natürliche Süße aus Banane.","note":"Ohne zugesetzten Zucker.","ingredients":[{"name":"Haferflocken","qty":350,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Milch oder Sojadrink","qty":900,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Wasser","qty":200,"unit":"ml","group":"Gewürze & Sonstiges","optional":false},{"name":"Backkakao, ungesüßt","qty":20,"unit":"g","group":"Gewürze & Sonstiges","optional":false},{"name":"Bananen","qty":3,"unit":"Stk","group":"Gemüse & Obst","optional":false},{"name":"Skyr","qty":600,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Erdnussmus","qty":75,"unit":"g","group":"Nüsse, Samen & Fette","optional":false}],"steps":[{"title":"Schoko-Haferbasis","body":"Haferflocken, Milch, Wasser und Backkakao im TM6 10 Min. / 90 °C / Linkslauf / Stufe 2 kochen.","mode":"tm6","minutes":10},{"title":"Banane & Erdnussmus","body":"Bananen in Scheiben schneiden. Erdnussmus bei Bedarf mit warmer Milch verrühren.","mode":"hand"},{"title":"Servieren","body":"Porridge in Schüsseln füllen, Skyr, Banane und einen Klecks Erdnussmus darübergeben.","mode":"hand"}],"image":"hafer-schoko.webp","tags":["vegetarisch","thermomix"]}'::jsonb),
  ('hafer-kuerbis', '{"id":"hafer-kuerbis","title":"Hokkaido-Vanille-Porridge","category":"hafer","cuisine":"Müsli & Porridge","minutes":35,"servings":5,"servingLabel":"Personen","description":"Süßlich-nussig mit geröstetem Kürbis und Vanille.","note":"Kürbis am Vorabend rösten spart Zeit.","ingredients":[{"name":"Hokkaido","qty":450,"unit":"g","group":"Gemüse & Obst","optional":false},{"name":"Haferflocken","qty":300,"unit":"g","group":"Getreide & Kartoffeln","optional":false},{"name":"Milch oder Sojadrink","qty":850,"unit":"ml","group":"Milchprodukte & Eier","optional":false},{"name":"Wasser","qty":100,"unit":"ml","group":"Gewürze & Sonstiges","optional":false},{"name":"Skyr","qty":500,"unit":"g","group":"Milchprodukte & Eier","optional":false},{"name":"Kürbiskerne","qty":75,"unit":"g","group":"Nüsse, Samen & Fette","optional":false},{"name":"Vanille","qty":1,"unit":"Prise","group":"Gewürze & Sonstiges","optional":false},{"name":"Zimt","qty":0.5,"unit":"TL","group":"Gewürze & Sonstiges","optional":false}],"steps":[{"title":"Hokkaido rösten","body":"Kürbis würfeln und bei 220 °C etwa 20–25 Minuten weich rösten.","mode":"ofen","minutes":23},{"title":"Kürbispüree im TM6","body":"Mit 200 ml der Milch 15 Sek. / Stufe 6 pürieren und umfüllen.","mode":"tm6"},{"title":"Haferflocken im TM6 garen","body":"Haferflocken mit übrigen 650 ml Milch, Wasser, Zimt und Vanille 10 Min. / 90 °C / Linkslauf / Stufe 2 garen.","mode":"tm6","minutes":10},{"title":"Fertigstellen","body":"Kürbispüree unterrühren, mit Skyr und angerösteten Kürbiskernen servieren.","mode":"hand"}],"image":"hafer-kuerbis.webp","tags":["vegetarisch","thermomix"]}'::jsonb)
